toolArgs.file_text:
.message-bubble {
    position: relative;
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    transition: background 0.1s;
}

.message-bubble:hover {
    background: #f5f5f5;
}

.message-bubble.highlighted {
    background: #e8f0fe;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.15rem;
}

.author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #1a1a1a;
}

.timestamp {
    font-size: 0.75rem;
    color: #888;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.45;
    color: #333;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem;
    margin-top: 0.35rem;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.15rem 0.5rem;
    background: #f0f0f0;
    border: 1px solid #ddd;
    border-radius: 999px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.1s;
}

.reaction-badge:hover {
    background: #e0e0f8;
    border-color: #b0b0d8;
}

.reaction-count {
    font-size: 0.75rem;
    color: #555;
}

.thread-link {
    display: inline-block;
    margin-top: 0.25rem;
    padding: 0;
    background: none;
    border: none;
    color: #4a90d9;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
}

.thread-link:hover {
    text-decoration: underline;
}

.hover-actions {
    position: absolute;
    top: -0.25rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 0.2rem;
    box-shadow: 0 2px 6px rgba(0,0,0,0.1);
    z-index: 10;
}

.action-btn {
    padding: 0.25rem 0.5rem;
    background: none;
    border: none;
    border-radius: 4px;
    font-size: 0.78rem;
    cursor: pointer;
    white-space: nowrap;
}

.action-btn:hover {
    background: #f0f0f0;
}

.emoji-picker {
    position: absolute;
    top: -0.25rem;
    right: 0.5rem;
    transform: translateY(-100%);
    display: flex;
    gap: 0.2rem;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 0.35rem;
    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
    z-index: 11;
}

.emoji-btn {
    width: 2rem;
    height: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    background: none;
    border: none;
    border-radius: 4px;
    font-size: 1.15rem;
    cursor: pointer;
}

.emoji-btn:hover {
    background: #f0f0f0;
}

