+                }
+            </div>
+
+            <MessageInput Placeholder="@($"Message #{activeChannel.Name}")"
+                          OnSubmit="SendMessage" />
+        }
+        else
+        {
+            <div class="empty-state">
+                <p>Select a channel to start chatting</p>
+            </div>
+        }
+    </div>
+
+    @if (isThreadOpen)
+    {
+        <div class="chat-thread">
+            <ThreadPanel RootMessage="threadRootMessage"
+                         Replies="threadReplies"
+                         OnClose="CloseThread"
+                         OnSendReply="SendThreadReply" />
+        </div>
+    }
+</div>
+
+@code {
+    private List<Channel> channels = [];
+    private List<Message> messages = [];
+    private Dictionary<int, int> replyCounts = new();
+    private Channel? activeChannel;
+    private int activeChannelId;
+
+    private bool isThreadOpen;
+    private int threadRootId;
+    private Message? threadRootMessage;
+    private List<Message> threadReplies = [];
+
+    private bool isLoadingMore;
+    private bool hasMoreMessages = true;
+    private const int PageSize = 30;
+
+    private ElementReference messageListRef;
+
+    protected override async Task OnInitializedAsync()
+    {
+        channels = await ChatService.GetChannelsAsync();
+        if (channels.Count > 0)
+        {
+            await SelectChannel(channels[0].Id);
+        }
+    }
+
+    private async Task SelectChannel(int channelId)
+    {
+        activeChannelId = channelId;
+        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
+        messages = [];
+        replyCounts.Clear();
+        hasMoreMessages = true;
+
+        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
+        messages = loaded;
+        hasMoreMessages = loaded.Count >= PageSize;
+        BuildReplyCounts();
+
+        await ChatService.MarkChannelReadAsync(channelId);
+
+        if (isThreadOpen)
+        {
+            CloseThread();
+        }
+    }
+
+    private async Task LoadMoreMessages()
+    {
+        if (isLoadingMore || !hasMoreMessages) return;
+        isLoadingMore = true;
+
+        var older = await ChatService.GetMessagesAsync(activeChannelId, messages.Count, PageSize);
+        hasMoreMessages = older.Count >= PageSize;
+        messages.InsertRange(0, older);
+        BuildReplyCounts();
+
+        isLoadingMore = false;
+    }
+
+    private async Task HandleScroll()
+    {
+        // Scroll-to-top detection is handled via the "Load older messages" button
+        // as a reliable fallback without JS interop.
+    }
+
+    private async Task SendMessage(string content)
+    {
+        if (activeChannel is null) return;
+        var msg = await ChatService.SendMessageAsync(activeChannel.Id, content, null);
+        messages.Add(msg);
+    }
+
+    private async Task OpenThread(int messageId)
+    {
+        threadRootId = messageId;
+        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
+        threadReplies = await ChatService.GetThreadAsync(messageId);
+        isThreadOpen = true;
+    }
+
+    private void CloseThread()
+    {
+        isThreadOpen = false;
+        threadRootMessage = null;
+        threadReplies = [];
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (activeChannel is null) return;
+        var reply = await ChatService.SendMessageAsync(activeChannel.Id, content, threadRootId);
+        threadReplies.Add(reply);
+        UpdateReplyCount(threadRootId, threadReplies.Count);
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+
+        // Optimistically update the reaction in the local message list
+        var target = messages.FirstOrDefault(m => m.Id == args.MessageId);
+        if (target is not null)
+        {
+            var existing = target.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
+            if (existing is not null)
+            {
+                existing.Users.Add("You");
+            }
+            else
+            {
+                target.Reactions.Add(new Reaction(args.Emoji, ["You"]));
+            }
+        }
+    }
+
+    private void BuildReplyCounts()
+    {
+        replyCounts.Clear();
+        foreach (var msg in messages.Where(m => m.ReplyToId is not null))
+        {
+            var rootId = msg.ReplyToId!.Value;
+            replyCounts[rootId] = replyCounts.GetValueOrDefault(rootId) + 1;
+        }
+    }
+
+    private void UpdateReplyCount(int rootId, int count) => replyCounts[rootId] = count;
+
+    private int GetReplyCount(int messageId) => replyCounts.GetValueOrDefault(messageId);
+}
+

toolArgs.file_text:
.chat-container {
    display: flex;
    height: 100vh;
    width: 100%;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

/* Sidebar — ~20% */
.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

/* Main area — 55% normally, 80% when thread is closed */
.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: #fff;
    overflow: hidden;
}

.chat-main.expanded {
    /* No thread panel — main area takes remaining space */
}

/* Thread panel — 25% */
.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 420px;
    flex-shrink: 0;
}

/* Main header */
.main-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e0e0e0;
    background: #fff;
}

.main-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #1a1a1a;
}

.header-desc {
    display: block;
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.15rem;
}

/* Message list */
.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

/* Load indicator */
.load-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #888;
    font-size: 0.85rem;
}

.load-more-btn {
    background: none;
    border: 1px solid #ccc;
    border-radius: 4px;
    padding: 0.35rem 1rem;
    color: #4a90d9;
    font-size: 0.8rem;
    cursor: pointer;
}

.load-more-btn:hover {
    background: #f5f5f5;
    border-color: #4a90d9;
}

/* Empty state */
.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #888;
    font-size: 1rem;
}

